package core

import (
	"fmt"
	"strings"
	"testing"

	"github.com/microsoft/Hybrid-Computer-Use/computer-use/internal/contract"
)

func TestIncrementalTreeOnlyWhenSafeAndCheaper(t *testing.T) {
	// Requiring an identical line count is too strong a proxy for "no
	// structural change": opening a menu, showing a dialog or adding a list row
	// all change the count, and those are the most common actions.
	//
	// The real safety invariant is finer. The element index is printed in each
	// line, and StableIndexer derives it from the tree path, role and name, so
	//
	//     byte-identical line  =>  same path, role and name  =>  same index
	//
	// Conversely, inserting a node changes the paths of later siblings, which
	// receive new indices and therefore new line text, so they always appear in
	// the diff. A large reorder exceeds the size thresholds and falls back to
	// the full tree, so the mechanism corrects itself when indices shift.
	base := func(lines ...string) *AppSnapshot { return &AppSnapshot{TreeLines: lines} }

	unchanged, ok := incrementalTree(base("a", "b", "c"), base("a", "b", "c"))
	if !ok || len(unchanged) != 1 || !strings.Contains(unchanged[0], "0 changes") {
		t.Fatalf("identical trees must yield only a zero-change summary, got ok=%v diff=%v", ok, unchanged)
	}

	diff, ok := incrementalTree(base("a", "b", "c", "d", "e", "f"),
		base("a", "b", "X", "d", "e", "f"))
	if !ok {
		t.Fatal("a single changed line should use the incremental diff")
	}
	if len(diff) != 3 || diff[1] != "-c" || diff[2] != "+X" {
		t.Fatalf("a replaced line should yield -old +new, got %v", diff)
	}
	if !strings.Contains(diff[0], "Existing rN refs remain bound") {
		t.Fatal("diff header must state that unaffected short refs remain bound")
	}

	// Pure insertion: the most common change after an action, which a
	// line-count criterion would reject.
	diff, ok = incrementalTree(base("a", "b", "c", "d", "e", "f", "g"),
		base("a", "b", "NEW", "c", "d", "e", "f", "g"))
	if !ok {
		t.Fatal("pure insertion should use the incremental diff, not fall back to the full tree")
	}
	if len(diff) != 2 || diff[1] != "+NEW" {
		t.Fatalf("pure insertion should yield only +new, got %v", diff)
	}

	// Pure deletion.
	diff, ok = incrementalTree(base("a", "b", "GONE", "c", "d", "e", "f"),
		base("a", "b", "c", "d", "e", "f"))
	if !ok {
		t.Fatal("pure deletion should use the incremental diff")
	}
	if len(diff) != 2 || diff[1] != "-GONE" {
		t.Fatalf("pure deletion should yield only -old, got %v", diff)
	}

	if _, ok := incrementalTree(base("a", "b", "c"), base("X", "Y", "c")); ok {
		t.Fatal("when most lines change, the diff should fall back to the full tree")
	}
	if _, ok := incrementalTree(nil, base("a")); ok {
		t.Fatal("without a previous snapshot there must be no incremental diff")
	}
}

func TestIncrementalTreeRejectsRootOrSerializerViewChanges(t *testing.T) {
	before := &AppSnapshot{
		WindowHandle: "pid1/win0/frame",
		TreeLines:    []string{"a", "b"},
		projection:   snapshotProjection{View: contract.TreeViewWorking},
	}
	otherRoot := &AppSnapshot{
		WindowHandle: "pid1/win1/frame",
		TreeLines:    []string{"a", "b"},
		projection:   snapshotProjection{View: contract.TreeViewWorking},
	}
	if _, ok := incrementalTree(before, otherRoot); ok {
		t.Fatal("different root windows must never share an incremental address-space claim")
	}

	fullView := &AppSnapshot{
		WindowHandle: "pid1/win0/frame",
		TreeLines:    []string{"a", "b"},
		projection:   snapshotProjection{View: contract.TreeViewFull},
	}
	if _, ok := incrementalTree(before, fullView); ok {
		t.Fatal("working and full serializer views must not be diffed as one tree")
	}
}

// TestIncrementalTreeKeepsLineDiffForShortLines checks that short lines keep
// the plain -/+ diff form.
func TestIncrementalTreeKeepsLineDiffForShortLines(t *testing.T) {
	base := func(lines ...string) *AppSnapshot { return &AppSnapshot{TreeLines: lines} }
	diff, ok := incrementalTree(base("a", "b", "c", "d", "e", "f"),
		base("a", "b", "X", "d", "e", "f"))
	if !ok {
		t.Fatal("replacing one short line should still use the incremental diff")
	}
	if len(diff) != 3 || diff[1] != "-c" || diff[2] != "+X" {
		t.Fatalf("short lines must not be summarized and should stay -old +new, got %v", diff)
	}
}

func TestIncrementalTreeRejectsNearFullDynamicPageDiff(t *testing.T) {
	before := &AppSnapshot{TreeLines: make([]string, 0, 120)}
	after := &AppSnapshot{TreeLines: make([]string, 0, 120)}
	for index := 0; index < 120; index++ {
		before.TreeLines = append(
			before.TreeLines,
			fmt.Sprintf("%d list item \"Old vehicle %03d\"", index, index),
		)
		after.TreeLines = append(
			after.TreeLines,
			fmt.Sprintf("%d list item \"New vehicle %03d\"", index, index),
		)
	}
	if _, ok := incrementalTree(before, after); ok {
		t.Fatal("a near-full dynamic-page diff must use compact action context")
	}
}

func TestActionFallbackReturnsFocusedContextNotWholeTree(t *testing.T) {
	snapshot := editorFormSnapshot()
	typedTreeTextForTest(t, snapshot)
	lines := compactActionObservationLines(snapshot)
	text := strings.Join(lines, "\n")
	if !strings.Contains(text, "focus:") ||
		!strings.Contains(text, `textbox "Name"`) {
		t.Fatalf("compact action observation lacks focused context:\n%s", text)
	}
	if strings.Contains(text, `status "Ready"`) {
		t.Fatalf("compact action observation replayed unrelated window state:\n%s", text)
	}
}

func TestActionFallbackPrefersChangedContentWhenFocusIsNavigation(t *testing.T) {
	snapshot := &AppSnapshot{
		TreeLines: []string{
			"\t0 frame \"Settings\"",
			"\t\t1 tree \"Navigation\"",
			"\t\t\t2 tree item \"Composition\" [focused selected]",
			"\t\t3 document web \"Composition Settings\"",
			"\t\t\t4 checkbox \"Automatically quote\"",
		},
		Elements: []ElementRecord{
			{Index: 0, RuntimeID: []int{0}, ControlType: "frame", Name: "Settings"},
			{Index: 1, RuntimeID: []int{0, 0}, ControlType: "tree", Name: "Navigation"},
			{Index: 2, RuntimeID: []int{0, 0, 0}, ControlType: "tree item", Name: "Composition", States: "[focused selected]"},
			{Index: 3, RuntimeID: []int{0, 1}, ControlType: "document web", Name: "Composition Settings"},
			{Index: 4, RuntimeID: []int{0, 1, 0}, ControlType: "check box", Name: "Automatically quote"},
		},
		Scope:           contract.AXScopeWindow,
		contentRevision: "c1:changed",
	}
	typedTreeTextForTest(t, snapshot)
	snapshot.contentRoot = &snapshot.Elements[3]

	lines := compactActionObservationLines(snapshot, nil)
	text := strings.Join(lines, "\n")
	if !strings.Contains(text, "content:") ||
		!strings.Contains(text, `checkbox "Automatically quote"`) {
		t.Fatalf("navigation fallback omitted changed content:\n%s", text)
	}
	if strings.Contains(text, `tree item "Composition"`) {
		t.Fatalf("navigation fallback returned only the old focused node:\n%s", text)
	}
	service := NewService()
	result, _, returned, compact, fullTree :=
		service.renderAXDiffOrCompactObservation(snapshot, nil)
	if !returned || !compact || fullTree ||
		result.StructuredContent["final_observation_kind"] != "content" {
		t.Fatalf("content fallback kind is inconsistent: %#v",
			result.StructuredContent)
	}
}

func popupMenuSnapshot(t *testing.T, menuOpen bool) *AppSnapshot {
	t.Helper()
	snapshot := &AppSnapshot{
		App:          AppDescriptor{Name: "Paint", PID: 42},
		WindowTitle:  "Paint",
		WindowHandle: "0x42",
		SnapshotID:   "paint-menu",
		Elements: []ElementRecord{
			{Index: 0, RuntimeID: []int{0}, ControlType: "frame", Name: "Paint"},
			{Index: 1, RuntimeID: []int{0, 0}, ControlType: "menu bar"},
			{Index: 2, RuntimeID: []int{0, 0, 0}, ControlType: "menu item", Name: "Settings", States: "[has-click-action]"},
			{Index: 3, RuntimeID: []int{0, 1}, ControlType: "panel", Name: "Canvas", States: "[focused]"},
			{Index: 4, RuntimeID: []int{0, 1, 0}, ControlType: "scroll bar", Name: "Horizontal"},
		},
		Scope: contract.AXScopeWindow,
	}
	if menuOpen {
		snapshot.Elements = append(snapshot.Elements,
			ElementRecord{Index: 5, RuntimeID: []int{0, 0, 0, 0}, ControlType: "menu item", Name: "Configure Paint...", States: "[has-click-action]"},
			ElementRecord{Index: 6, RuntimeID: []int{0, 0, 0, 1}, ControlType: "check menu item", Name: "Show Rulers", States: "[has-click-action]"},
		)
	}
	typedTreeTextForTest(t, snapshot)
	for _, node := range snapshot.AXSnapshot.ByIndex {
		if node != nil && node.Name == "Settings" {
			if node.Ref == "" {
				// The fixture only needs the acted element to be addressable.
				node.Ref = "r90"
			}
			snapshot.actedRef = node.Ref
		}
	}
	if snapshot.actedRef == "" {
		t.Fatal("fixture has no Settings menu item")
	}
	return snapshot
}

// A click that opens a menu leaves focus on the canvas or the opener; the
// compact result must list the opened items instead, so the caller does not
// need another find to see them.
func TestCompactActionObservationShowsOpenedPopupItems(t *testing.T) {
	snapshot := popupMenuSnapshot(t, true)
	lines := compactActionObservationLines(snapshot, nil)
	text := strings.Join(lines, "\n")
	if len(lines) == 0 || lines[0] != "popup:" ||
		!strings.Contains(text, `menuitem "Configure Paint..."`) ||
		!strings.Contains(text, `"Show Rulers"`) {
		t.Fatalf("opened menu items missing from compact result:\n%s", text)
	}
	if strings.Contains(text, "Canvas") {
		t.Fatalf("compact result kept the focused canvas instead of the popup:\n%s", text)
	}
	service := NewService()
	result, _, returned, compact, _ :=
		service.renderAXDiffOrCompactObservation(snapshot, nil)
	if !returned || !compact ||
		result.StructuredContent["final_observation_kind"] != "popup" {
		t.Fatalf("popup observation kind is inconsistent: %#v", result.StructuredContent)
	}
}

func TestCompactActionObservationKeepsFocusWhenNoPopupOpened(t *testing.T) {
	snapshot := popupMenuSnapshot(t, false)
	lines := compactActionObservationLines(snapshot, nil)
	if len(lines) == 0 || lines[0] != "focus:" {
		t.Fatalf("an action that opened nothing must keep the focus view, got %v", lines)
	}
}

package core

import (
	"bytes"
	"encoding/json"
	"strings"
	"testing"

	"github.com/microsoft/Hybrid-Computer-Use/computer-use/internal/contract"
)

// Codex (openai/codex codex-rs/tools/src/json_schema.rs and
// json_schema/compaction.rs, revision ce0323f2f2d3b25e82806cd555237da3db4e1897)
// rewrites a tool input schema before the model sees it and,
// above 5,000 bytes, compacts it in up to four stages until it fits: strip
// descriptions, inline-drop $defs, collapse nesting at depth 3, prune
// oneOf/anyOf/allOf. This test reproduces those rules and reports each
// public tool's size after every stage. It only reports; it does not fail.

const codexSchemaBudget = 5000

var codexCompositions = []string{"anyOf", "oneOf", "allOf"}

var codexFieldOrder = []string{
	"$ref", "type", "description", "encrypted", "enum", "items", "minItems",
	"properties", "required", "additionalProperties", "anyOf", "oneOf", "allOf",
	"$defs", "definitions",
}

var codexPrimitiveTypes = map[string]bool{
	"string": true, "number": true, "boolean": true, "integer": true,
	"object": true, "array": true, "null": true,
}

type codexStage struct {
	name  string
	bytes int
}

func codexCompact(schema map[string]any) []codexStage {
	value := cloneJSON(jsonRoundTrip(schema)).(map[string]any)
	if _, ok := value["properties"]; !ok {
		value["properties"] = map[string]any{}
	}
	value = codexSanitize(value).(map[string]any)
	codexPruneDefs(value)
	stages := []codexStage{{"normalized", codexSize(value)}}
	for _, stage := range []struct {
		name string
		run  func(any) any
	}{
		{"strip_descriptions", func(v any) any { codexStripDescriptions(v); return v }},
		{"drop_defs", codexDropDefs},
		{"collapse_depth3", func(v any) any { return codexCollapse(v, 0) }},
		{"prune_compositions", codexPruneCompositions},
	} {
		if codexSize(value) <= codexSchemaBudget {
			break
		}
		value = stage.run(value).(map[string]any)
		stages = append(stages, codexStage{stage.name, codexSize(value)})
	}
	return stages
}

func jsonRoundTrip(value any) any {
	encoded, _ := json.Marshal(value)
	var decoded any
	_ = json.Unmarshal(encoded, &decoded)
	return decoded
}

func codexSanitize(value any) any {
	switch typed := value.(type) {
	case bool:
		return map[string]any{"type": "string"}
	case []any:
		for index, item := range typed {
			typed[index] = codexSanitize(item)
		}
		return typed
	case map[string]any:
		if properties, ok := typed["properties"].(map[string]any); ok {
			for key, item := range properties {
				properties[key] = codexSanitize(item)
			}
		}
		for _, key := range []string{"items", "prefixItems"} {
			if item, ok := typed[key]; ok {
				typed[key] = codexSanitize(item)
			}
		}
		if item, ok := typed["additionalProperties"]; ok {
			if _, isBool := item.(bool); !isBool {
				typed["additionalProperties"] = codexSanitize(item)
			}
		}
		for _, key := range codexCompositions {
			if item, ok := typed[key]; ok {
				typed[key] = codexSanitize(item)
			}
		}
		for _, key := range []string{"$defs", "definitions"} {
			if defs, ok := typed[key].(map[string]any); ok {
				for name, item := range defs {
					defs[name] = codexSanitize(item)
				}
			} else if _, present := typed[key]; present {
				delete(typed, key)
			}
		}
		if constant, ok := typed["const"]; ok {
			delete(typed, "const")
			typed["enum"] = []any{constant}
		}
		types := []string{}
		switch kind := typed["type"].(type) {
		case string:
			if codexPrimitiveTypes[kind] {
				types = []string{kind}
			}
		case []any:
			for _, item := range kind {
				if name, ok := item.(string); ok && codexPrimitiveTypes[name] {
					types = append(types, name)
				}
			}
		}
		hasComposition := false
		for _, key := range codexCompositions {
			if _, ok := typed[key]; ok {
				hasComposition = true
			}
		}
		if _, hasRef := typed["$ref"]; len(types) == 0 && (hasRef || hasComposition) {
			return typed
		}
		if len(types) == 0 {
			switch {
			case hasAny(typed, "properties", "required", "additionalProperties"):
				types = []string{"object"}
			case hasAny(typed, "items", "prefixItems"):
				types = []string{"array"}
			case hasAny(typed, "enum", "format"):
				types = []string{"string"}
			case hasAny(typed, "minimum", "maximum", "exclusiveMinimum", "exclusiveMaximum", "multipleOf"):
				types = []string{"number"}
			default:
				for key := range typed {
					delete(typed, key)
				}
				return typed
			}
		}
		if len(types) == 1 {
			typed["type"] = types[0]
		} else {
			list := make([]any, len(types))
			for index, name := range types {
				list[index] = name
			}
			typed["type"] = list
		}
		if contract.ContainsString(types, "object") {
			if _, ok := typed["properties"]; !ok {
				typed["properties"] = map[string]any{}
			}
		}
		if contract.ContainsString(types, "array") {
			if _, ok := typed["items"]; !ok {
				typed["items"] = map[string]any{"type": "string"}
			}
		}
		return typed
	default:
		return value
	}
}

func hasAny(object map[string]any, keys ...string) bool {
	for _, key := range keys {
		if _, ok := object[key]; ok {
			return true
		}
	}
	return false
}

// codexChildren lists the subschema locations Codex walks.
func codexChildren(object map[string]any, includeDefs bool) [][2]string {
	var children [][2]string
	if properties, ok := object["properties"].(map[string]any); ok {
		for _, key := range contract.SortedKeys(properties) {
			children = append(children, [2]string{"properties", key})
		}
	}
	for _, key := range []string{"items", "anyOf", "oneOf", "allOf"} {
		if _, ok := object[key]; ok {
			children = append(children, [2]string{key, ""})
		}
	}
	if item, ok := object["additionalProperties"]; ok {
		if _, isBool := item.(bool); !isBool {
			children = append(children, [2]string{"additionalProperties", ""})
		}
	}
	if includeDefs {
		for _, key := range []string{"$defs", "definitions"} {
			if defs, ok := object[key].(map[string]any); ok {
				for _, name := range contract.SortedKeys(defs) {
					children = append(children, [2]string{key, name})
				}
			}
		}
	}
	return children
}

func codexGet(object map[string]any, child [2]string) any {
	if child[1] != "" {
		return object[child[0]].(map[string]any)[child[1]]
	}
	return object[child[0]]
}

func codexSet(object map[string]any, child [2]string, value any) {
	if child[1] != "" {
		object[child[0]].(map[string]any)[child[1]] = value
		return
	}
	object[child[0]] = value
}

func codexRefs(value any, refs *[]string, skipDefs bool) {
	switch typed := value.(type) {
	case []any:
		for _, item := range typed {
			codexRefs(item, refs, skipDefs)
		}
	case map[string]any:
		if ref, ok := typed["$ref"].(string); ok && strings.HasPrefix(ref, "#/$defs/") {
			*refs = append(*refs, ref[strings.LastIndex(ref, "/")+1:])
		}
		for _, child := range codexChildren(typed, !skipDefs) {
			codexRefs(codexGet(typed, child), refs, skipDefs)
		}
	}
}

func codexPruneDefs(value map[string]any) {
	var pending []string
	codexRefs(value, &pending, true)
	reachable := map[string]bool{}
	defs, _ := value["$defs"].(map[string]any)
	for len(pending) > 0 {
		name := pending[len(pending)-1]
		pending = pending[:len(pending)-1]
		if reachable[name] {
			continue
		}
		reachable[name] = true
		if def, ok := defs[name]; ok {
			codexRefs(def, &pending, false)
		}
	}
	if defs != nil {
		for name := range defs {
			if !reachable[name] {
				delete(defs, name)
			}
		}
		if len(defs) == 0 {
			delete(value, "$defs")
		}
	}
}

func codexNormalize(value any) any {
	switch typed := value.(type) {
	case []any:
		out := make([]any, len(typed))
		for index, item := range typed {
			out[index] = codexNormalize(item)
		}
		return out
	case map[string]any:
		out := orderedObject{}
		for _, key := range codexFieldOrder {
			item, ok := typed[key]
			if !ok {
				continue
			}
			switch key {
			case "items":
				item = codexNormalize(item)
			case "properties", "$defs", "definitions":
				if nested, ok := item.(map[string]any); ok {
					inner := orderedObject{}
					for _, name := range contract.SortedKeys(nested) {
						inner = append(inner, orderedField{name, codexNormalize(nested[name])})
					}
					item = inner
				}
			case "additionalProperties":
				if _, isBool := item.(bool); !isBool {
					item = codexNormalize(item)
				}
			case "anyOf", "oneOf", "allOf":
				item = codexNormalize(item)
			}
			out = append(out, orderedField{key, item})
		}
		return out
	default:
		return value
	}
}

type orderedField struct {
	key   string
	value any
}

type orderedObject []orderedField

func (object orderedObject) MarshalJSON() ([]byte, error) {
	var out bytes.Buffer
	out.WriteByte('{')
	for index, field := range object {
		if index > 0 {
			out.WriteByte(',')
		}
		key, _ := json.Marshal(field.key)
		value, err := marshalNoEscape(field.value)
		if err != nil {
			return nil, err
		}
		out.Write(key)
		out.WriteByte(':')
		out.Write(value)
	}
	out.WriteByte('}')
	return out.Bytes(), nil
}

func marshalNoEscape(value any) ([]byte, error) {
	var out bytes.Buffer
	encoder := json.NewEncoder(&out)
	encoder.SetEscapeHTML(false)
	if err := encoder.Encode(value); err != nil {
		return nil, err
	}
	return bytes.TrimRight(out.Bytes(), "\n"), nil
}

func codexSize(value any) int {
	encoded, _ := marshalNoEscape(codexNormalize(value))
	return len(encoded)
}

func codexStripDescriptions(value any) {
	switch typed := value.(type) {
	case []any:
		for _, item := range typed {
			codexStripDescriptions(item)
		}
	case map[string]any:
		delete(typed, "description")
		for _, child := range codexChildren(typed, true) {
			codexStripDescriptions(codexGet(typed, child))
		}
	}
}

func codexRewriteRefs(value any) any {
	switch typed := value.(type) {
	case []any:
		for index, item := range typed {
			typed[index] = codexRewriteRefs(item)
		}
		return typed
	case map[string]any:
		if ref, ok := typed["$ref"].(string); ok && strings.HasPrefix(ref, "#/$defs/") {
			return map[string]any{}
		}
		for _, child := range codexChildren(typed, false) {
			codexSet(typed, child, codexRewriteRefs(codexGet(typed, child)))
		}
		return typed
	default:
		return value
	}
}

func codexDropDefs(value any) any {
	value = codexRewriteRefs(value)
	object := value.(map[string]any)
	delete(object, "$defs")
	delete(object, "definitions")
	return object
}

func codexCollapse(value any, depth int) any {
	switch typed := value.(type) {
	case []any:
		for index, item := range typed {
			typed[index] = codexCollapse(item, depth)
		}
		return typed
	case map[string]any:
		if depth >= 3 && hasAny(typed, "items", "anyOf", "oneOf", "allOf", "properties", "additionalProperties", "$ref") {
			return map[string]any{}
		}
		for _, child := range codexChildren(typed, false) {
			codexSet(typed, child, codexCollapse(codexGet(typed, child), depth+1))
		}
		return typed
	default:
		return value
	}
}

func codexPruneCompositions(value any) any {
	switch typed := value.(type) {
	case []any:
		for index, item := range typed {
			typed[index] = codexPruneCompositions(item)
		}
		return typed
	case map[string]any:
		if hasAny(typed, codexCompositions...) {
			return map[string]any{}
		}
		for _, child := range codexChildren(typed, false) {
			codexSet(typed, child, codexPruneCompositions(codexGet(typed, child)))
		}
		return typed
	default:
		return value
	}
}

func itoa(value int) string {
	encoded, _ := json.Marshal(value)
	return string(encoded)
}

// TestAXSchemaSurvivesClientCompaction keeps the AX schema under the Codex
// compaction budget. Above it, Codex strips descriptions and then replaces
// nested objects with {}, so the model no longer sees the action fields and
// writes shapes the runtime rejects.
func TestAXSchemaSurvivesClientCompaction(t *testing.T) {
	ax := findToolDefinition(t, "AX")
	stages := codexCompact(ax.InputSchema)
	if len(stages) != 1 || stages[0].bytes > codexSchemaBudget {
		t.Fatalf("AX schema triggers client compaction: %+v", stages)
	}
	normalized := codexNormalize(codexSanitize(cloneJSON(jsonRoundTrip(ax.InputSchema)))).(orderedObject)
	encoded, err := marshalNoEscape(normalized)
	if err != nil {
		t.Fatal(err)
	}
	var visible map[string]any
	if err := json.Unmarshal(encoded, &visible); err != nil {
		t.Fatal(err)
	}
	properties := visible["properties"].(map[string]any)
	actionFields := properties["actions"].(map[string]any)["items"].(map[string]any)["properties"].(map[string]any)
	for _, field := range []string{"type", "ref", "title", "text", "keys", "value", "direction", "pages",
		"window", "query", "state", "gone", "settle", "timeout_ms"} {
		if _, ok := actionFields[field]; !ok {
			t.Fatalf("action field %q is not visible after normalization: %v", field, contract.SortedKeys(actionFields))
		}
	}
	types := actionFields["type"].(map[string]any)["enum"].([]any)
	if len(types) != len(contract.AXActionTypes) {
		t.Fatalf("action type enum lost values: %v", types)
	}
	query := visible["$defs"].(map[string]any)["query"].(map[string]any)["properties"].(map[string]any)
	for _, field := range contract.AXFindFilters {
		if _, ok := query[field]; !ok {
			t.Fatalf("query field %q is not visible: %v", field, contract.SortedKeys(query))
		}
	}
	if _, present := properties["until"]; present {
		t.Fatal("the removed until field is still published")
	}
	t.Logf("AX schema: raw=%d normalized=%d budget=%d", len(mustJSON(t, ax.InputSchema)), stages[0].bytes, codexSchemaBudget)
}

func mustJSON(t *testing.T, value any) []byte {
	t.Helper()
	encoded, err := json.Marshal(value)
	if err != nil {
		t.Fatal(err)
	}
	return encoded
}

