func TestSemanticTargetFromRefPreservesSelectorPredicates(t *testing.T) {
	ref := encodeScopedSemanticRef(
		`toggle button "Menu" [desc="View options"] [focused] [a=click]`,
		"pid145/win1/dialog",
	)
	target, err := semanticTargetFromAddress(ref)
	if err != nil {
